  // Applications
  "assistant.staff.applications.title": "Applications",
  "assistant.staff.applications.purpose": "People who have applied for your listings, and your decisions on them.",
  "assistant.staff.applications.q1": "What stages does an application go through?",
  "assistant.staff.applications.a1": "Submitted, then screening once you press Screen, then approved or rejected.",
  "assistant.staff.applications.q2": "What does Screen work out?",
  "assistant.staff.applications.a2": "It compares the applicant's monthly income with the advertised rent and checks the credit score. Income of at least 3 times the rent with a score of 650 or more recommends approve; income under 3 times the rent or a score below 550 recommends decline; anything in between recommends review.",
